/**
 * Admin Authentication Service
 * 
 * This is a temporary service to enable admin login in development mode
 */
import api from './api';

/**
 * Login with admin credentials
 * @param {string} email - Admin email
 * @param {string} password - Admin password
 * @returns {Promise} - The response promise
 */
export const adminLogin = async (email, password) => {
  // For development, use mock data with admin role
  
  // Simulate API delay
  await new Promise(resolve => setTimeout(resolve, 500));
  
  // Check if using admin credentials
  const isAdmin = email === 'admin@cashheros.com' && password === 'admin123';
  
  if (!isAdmin) {
    throw new Error('Invalid admin credentials');
  }
  
  // Generate mock tokens
  const mockAccessToken = 'mock_admin_access_' + Math.random().toString(36).substring(2, 15);
  const mockRefreshToken = 'mock_admin_refresh_' + Math.random().toString(36).substring(2, 15);
  
  // Create mock response data with admin role
  const mockResponseData = {
    accessToken: mockAccessToken,
    refreshToken: mockRefreshToken,
    user: {
      id: 'admin1',
      email: email,
      firstName: 'Admin',
      lastName: 'User',
      role: 'admin', // Set role to admin
      emailVerified: true,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString()
    }
  };
  
  // Store tokens in localStorage
  localStorage.setItem('accessToken', mockAccessToken);
  localStorage.setItem('refreshToken', mockRefreshToken);
  
  // Store admin user data in localStorage
  localStorage.setItem('cachedUserProfile', JSON.stringify({ user: mockResponseData.user }));
  localStorage.setItem('cachedUserProfileTimestamp', Date.now().toString());
  
  return mockResponseData;
};

export default {
  adminLogin
};
